export function expectedValue(task) {
 if(task.type==='category') return Object.fromEntries(task.items.map((x,i)=>[String(i), x.answer]));
 if(task.type==='match') return Object.fromEntries(task.items.map((x,i)=>[String(i),x.answer]));
 if(task.type==='order') return task.correct;
 return task.correct;
}
export function grade(task, value) {
 if(task.type === 'text') return null; // Bewusst keine automatische Freitextprüfung.
 if(task.type==='numeric') { const n=Number(String(value).replace(/\s/g,'').replace(',','.').replace('€',''));return Number.isFinite(n) && Math.abs(n-task.correct)<0.00001; }
 if(task.type==='single') return Number(value)===task.correct;
 if(task.type==='tf') return typeof value==='boolean' && value===task.correct;
 if(task.type==='multi') return Array.isArray(value) && value.length===task.correct.length && [...new Set(value.map(Number))].sort().join()===task.correct.slice().sort().join();
 if(task.type==='category' || task.type==='match') return value && typeof value==='object' && task.items.every((x,i)=>value[i]===x.answer);
 if(task.type==='order') return Array.isArray(value) && value.length===task.correct.length && value.join('|')===task.correct.join('|');
 return false;
}
export function taskXp(task){return ({1:20,2:35,3:55})[task.afb] + (task.bonus?25:0) + (task.chapter==='test'?10:0);}
export function earnedXp(progress){return ALL_TASKS.reduce((sum,t)=>sum+(progress.answers?.[t.id]?.correct?taskXp(t):0),0);}
export function wallet(progress){return Math.max(0,earnedXp(progress)-SHOP.filter(x=>progress.owned?.includes(x.id)).reduce((s,x)=>s+x.price,0));}
export function completedCount(progress){return TASKS.filter(t=>progress.answers?.[t.id]?.correct).length;}
export function newProgress(){return {answers:{},owned:[],appearance:{avatar:'default',pet:null,outfit:null},skills:{},lastChapter:'grundlagen',updatedAt:null};}
